async fn async_lock(mutex: &tokio::sync::Mutex<u64>) {
    let guard = mutex.lock()
        .await;
    remote_call().await;
}
async fn conditional(mutex: &std::sync::Mutex<u64>, early: bool) -> Result<(), Error> {
    let guard = mutex.lock()?;
    if early {
        drop(guard);
    }
    remote_call().await;
    Ok(())
}
async fn always_drops(mutex: &std::sync::Mutex<u64>) -> Result<(), Error> {
    let guard = mutex.lock()?;
    drop(guard);
    remote_call().await;
    Ok(())
}

