async fn write(db: &DatabaseConnection, input: &str) {
    db.execute_unprepared(&format!("SELECT * FROM {table}", table = "items")).await;
    db.execute_unprepared(&format!("SELECT * FROM {}", "items")).await;
    let mut sql = format!("DELETE FROM items WHERE name = {input}");
    {
        let sql = "SELECT 1";
        db.execute_unprepared(sql).await;
    }
    db.execute_unprepared(&sql).await;
    db.execute_unprepared(&format!("SELECT * FROM {}", input)).await;
    db.execute_unprepared(&format!("SELECT '{{input}}'")).await;
    sql = "SELECT 1".to_string();
    db.execute_unprepared(&sql).await;
}
